import request from '@/plugin/axios'
import cryptoJS from '@/libs/util.cryptoJS.js'

export function GetAllWork(data) {
	return request({
		url: '/GetAllWork',
		method: 'post',
		data: cryptoJS.aesEncryptObj2Obj(data)
	})
}

