<template>
	<div>
		<div>
			<el-button type="success" icon="el-icon-check" size="medium" @click="save" v-loading.fullscreen.lock="fullscreenLoading">保存</el-button>
			<el-button type="danger" icon="el-icon-back" size="medium" @click="back">返回</el-button>

		</div>
		<el-card shadow="never" style="margin-top: 10px;">
			<el-form ref="form" :model="form" label-width="100px" :rules="rules">
				<el-row>
					<el-col :span="6">
						<el-form-item label="素材名称:" prop="Name">
							<el-input v-model="form.Name" clearable></el-input>
						</el-form-item>
					</el-col>
					<el-col :span="6">
						<el-form-item label="好刷吗:" prop="Easy">
							<el-autocomplete v-model="form.Easy" :fetch-suggestions="querySearch" clearable style="width: 100%;"></el-autocomplete>
						</el-form-item>
					</el-col>
					<el-col :span="6">
						<el-form-item label="怪物:" prop="Monster">
							<el-input v-model="form.Monster" clearable></el-input>
						</el-form-item>
					</el-col>
					<el-col :span="6">
						<el-form-item label="地点:" prop="Address">
							<el-autocomplete v-model="form.Address" :fetch-suggestions="querySearch2" clearable style="width: 100%;"></el-autocomplete>
						</el-form-item>
					</el-col>
				</el-row>

				<el-row>
					<el-col :span="12">
						<el-form-item label="导航:">
							<el-input type="textarea" v-model="form.Navi" clearable :rows="3" maxlength="255" show-word-limit></el-input>
						</el-form-item>
					</el-col>
					<el-col :span="12">
						<el-form-item label="备注:">
							<el-input type="textarea" v-model="form.Remark" :rows="3" clearable maxlength="255" show-word-limit></el-input>
						</el-form-item>
					</el-col>
				</el-row>

				<el-row>
					<el-col :span="12">
						<el-form-item label="怪物图片:" v-if="uploadPicArgs.allowDownload">
							<el-upload :class="{hide:uploadPicArgs.isHide}" action="null" :accept="uploadPicArgs.accept" list-type="picture-card"
							 :on-exceed="handlePicExceed" :on-preview="handlePicPreview" multiple :limit="uploadPicArgs.limitCount"
							 :before-upload="beforePicUpload" :file-list="form.ArrayPic" :http-request="hanlePicUpload">
								<i slot="default" class="el-icon-plus"></i>
								<div slot="file" slot-scope="{file}">
									<img class="el-upload-list__item-thumbnail" :src="file.url" alt="">
									<span class="el-upload-list__item-actions">
										<span class="el-upload-list__item-preview" @click="handlePicPreview(file)">
											<i class="el-icon-zoom-in"></i>
										</span>
										<span class="el-upload-list__item-delete" @click="handlePicDownload(file)">
											<i class="el-icon-download"></i>
										</span>
										<span v-if="uploadPicArgs.allowDelete" class="el-upload-list__item-delete" @click="handlePicRemove(file)">
											<i class="el-icon-delete"></i>
										</span>
									</span>
								</div>
							</el-upload>
							<el-dialog :visible.sync="dialogVisible">
								<img width="90%" :src="dialogImageUrl" alt="">
							</el-dialog>
						</el-form-item>
						<el-button type="primary" @click="showlist">显示</el-button>
					</el-col>

					<el-col :span="12">
						<el-form-item label="攻略文件:">
							<el-upload action="null" :accept="uploadFileArgs.accept" :on-exceed="handleFileExceed" multiple :limit="uploadFileArgs.limitCount"
							 :http-request="hanleFileUpload" :file-list="form.ArrayFile" :before-remove="beforeFileRemove" :on-remove="handleFileRemove"
							 :before-upload="beforeFileUpload" :on-preview="handleFileDownload">
								<div v-if="uploadFileArgs.isHide">
									<el-button size="small" type="primary">点击上传</el-button>
									<span style="margin-left: 10px; font-size: small;">限制上传{{uploadFileArgs.limitCount}}个文件，每个不超过5m</span>
								</div>
							</el-upload>
						</el-form-item>
					</el-col>
				</el-row>
			</el-form>
		</el-card>

	</div>
</template>

<script>
	import {
		GetWorkByID,
		UpdateWorkByID,
		AddWork,
		GetWorkEasys,
		GetWorkAddress
	} from '@api/WorkInfo.js'

	import {
		UploadPic,
		UploadFile
	} from '@api/Upload.js'

	export default {
		data() {

			return {
				fullscreenLoading: false,
				Status: 1,
				form: {
					Name: '',
					Easy: '',
					Address: '',
					Monster: '',
					Navi: '',
					Remark: '',
					ArrayPic: [],
					ArrayFile: []
				},
				combolist: {
					easy: [],
					address: [],
				},


				//图片上传组件参数配置
				uploadPicArgs: {
					accept: '',
					allowUpload: false,
					allowDownload: false,
					allowDelete: false,
					isHide: false,
					limitCount: 0, //限制数量
					limitSize: 0, //限制文件大小
				},

				//文件上传组件参数配置
				uploadFileArgs: {
					accept: '',
					allowUpload: false,
					allowDownload: false,
					allowDelete: false,
					isHide: true, //是否隐藏上传
					limitCount: 0, //限制数量
					limitSize: 0, //限制文件大小
				},


				rules: {
					Name: [{
							required: true,
							message: '请输入素材名',
							trigger: 'blur'
						},
						{
							min: 2,
							max: 10,
							message: '长度在 2 到 50个字符',
							trigger: 'blur'
						}
					],
					Easy: [{
						required: true,
						message: '好刷吗？',
						trigger: 'blur'
					}],
					Address: [{
						required: true,
						message: '请输入地址',
						trigger: 'blur'
					}],
					Monster: [{
							required: true,
							message: '请输入怪物名称',
							trigger: 'blur'
						},
						{
							min: 1,
							max: 50,
							message: '长度在 1 到 50个字符',
							trigger: 'blur'
						}
					]
				},

				dialogImageUrl: '',
				dialogVisible: false


			}
		},
		props: {
			passID: String,
			authKeys: Array
		},
		mounted() {
			this.InitSelect()
			this.InitWork()
			this.InitPicUpload()
			this.InitFileUpload()
		},
		methods: {

			//图片上传控件用---
			//初始化图片控件参数
			InitPicUpload() {
				this.uploadPicArgs.allowUpload = (this.authKeys.indexOf('24') > -1) ? true : false
				this.uploadPicArgs.allowDownload = (this.authKeys.indexOf('25') > -1) ? true : false
				this.uploadPicArgs.allowDelete = (this.authKeys.indexOf('26') > -1) ? true : false
				this.uploadPicArgs.accept = 'image/jpeg,image/gif,image/png,image/bmp'
				this.uploadPicArgs.limitCount = 3
				this.uploadPicArgs.limitSize = 1
			},
			//图片选择超出限制数后
			handlePicExceed(files, fileList) {
				this.$message.warning('最多只能上传' + this.uploadPicArgs.limitCount + '个文件')
			},
			//图片上传前拦截类型和尺寸
			beforePicUpload(file) {
				let allowType = this.uploadPicArgs.accept.split(',')
				let type = file.type
				if (allowType.indexOf(type) === -1) {
					this.$message.error('只允许上传jpg、png、bmp、gif类型的图片')
					return false
				}

				let size = file.size / 1024 / 1024
				let ls = this.uploadPicArgs.limitSize
				if (size > ls) {
					this.$message.error('图片必须少于' + ls + 'm')
					return false
				}
			},
			//图片上传
			hanlePicUpload(e) {
				let formData = new FormData()
				formData.append(e.file.uid, e.file)
				UploadPic(formData) //注意这里不要有{}，会被强转为对象
					.then(res => {
						this.form.ArrayPic.push(res)
						this.checkUploadPiclimitCount() //更新图片上传限制，因为是异步获取的数据，必须在异步里执行						
					}).catch(err => {})
			},
			//图片删除，去掉列表内容
			handlePicRemove(file) {
				this.$confirm('确定删除 ' + file.name + ' ?', '提示', {
					confirmButtonText: '确定',
					cancelButtonText: '取消',
					type: 'warning'
				}).then(() => {
					let index = this.form.ArrayPic.indexOf(file)
					if (index > -1) {
						this.form.ArrayPic.splice(index, 1)
					}
					this.checkUploadPiclimitCount()
				}).catch(() => {})
			},
			//图片预览
			handlePicPreview(file) {
				this.dialogImageUrl = file.url;
				this.dialogVisible = true;
			},
			//图片下载
			handlePicDownload(file) {
				window.open(file.url)
			},
			//图片更新上传组件最大数量限制状态
			checkUploadPiclimitCount() {
				this.uploadPicArgs.isHide = this.form.ArrayPic.length >= this.uploadPicArgs.limitCount;
			},
			showlist() {
				console.log(this.form.ArrayFile)
			},
			//图片上传控件用---




			//文件上传控件用---
			//初始化文件控件参数
			InitFileUpload() {
				this.uploadFileArgs.allowUpload = (this.authKeys.indexOf('28') > -1) ? true : false
				this.uploadFileArgs.allowDownload = (this.authKeys.indexOf('29') > -1) ? true : false
				this.uploadFileArgs.allowDelete = (this.authKeys.indexOf('30') > -1) ? true : false
				this.uploadFileArgs.accept =
					'text/plain,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.openxmlformats-officedocument.presentationml.presentation,application/x-zip-compressed,application/octet-stream'
				this.uploadFileArgs.limitCount = 3
				this.uploadFileArgs.limitSize = 5
			},
			//文件超出限制数后
			handleFileExceed(files, fileList) {
				this.$message.warning('最多只能上传' + this.uploadFileArgs.limitCount + '个文件')
			},
			//文件上传前拦截类型和尺寸
			beforeFileUpload(file) {
				let allowType = this.uploadFileArgs.accept.split(',')
				let type = file.type
				if (allowType.indexOf(type) === -1) {
					this.$message.error('只允许上传txt、word、excel、ppt、pdf、zip、rar类型的文件')
					return false
				}

				let size = file.size / 1024 / 1024
				let ls = this.uploadFileArgs.limitSize
				if (size > ls) {
					this.$message.error('文件必须少于' + ls + 'm')
					return false
				}
			},
			//文件上传
			hanleFileUpload(e) {
				let formData = new FormData()
				formData.append(e.file.uid, e.file)
				UploadFile(formData) //注意这里不要有{}，会被强转为对象
					.then(res => {
						this.form.ArrayFile.push(res)
						this.checkUploadFilelimitCount() //更新图片上传限制，因为是异步获取的数据，必须在异步里执行						
					}).catch(err => {})
			},
			//文件删除前确认
			beforeFileRemove(file, fileList) {
				if (this.uploadFileArgs.allowDelete == false) {
					this.$message.warning('您没有删除权限')
					return false
				} else {
					return this.$confirm('确定删除 ' + file.name + ' ?', '提示')
				}
			},
			//文件删除后，去掉列表内容
			handleFileRemove(file, FileList) {
				let index = this.form.ArrayFile.indexOf(file)
				if (index > -1) {
					this.form.ArrayFile.splice(index, 1)
				}
				this.checkUploadFilelimitCount()
			},
			//文件下载
			handleFileDownload(file) {
				if (this.uploadFileArgs.allowDownload) {
					window.open(file.url)
				} else {
					this.$message.warning('您没有下载和查看权限')
				}

			},
			//文件更新上传组件最大数量限制状态
			checkUploadFilelimitCount() {
				if (this.uploadFileArgs.allowUpload && this.form.ArrayFile.length < this.uploadFileArgs.limitCount) {
					this.uploadFileArgs.isHide = true
				} else {
					this.uploadFileArgs.isHide = false
				}
			},
			//文件上传控件用---

			InitWork() {
				if (this.passID !== '') { //有ID，说明是编辑，才去查询数据
					GetWorkByID({
							ID: this.passID
						})
						.then(res => {
							this.Status = res.Status
							this.form = res
							this.checkUploadPiclimitCount() //更新图片上传限制，因为是异步获取的数据，必须在异步里执行	
							this.checkUploadFilelimitCount() //更新图片上传限制，因为是异步获取的数据，必须在异步里执行	
						}).catch(err => {})
				} else {}
			},

			InitSelect() {
				GetWorkEasys({})
					.then(res => {
						this.combolist.easy = res.list
					})
					.catch(err => {})
				GetWorkAddress({})
					.then(res => {
						this.combolist.address = res.list
					})
					.catch(err => {})
			},

			back() {
				this.$emit('goBack')
			},

			save() {
				this.$refs.form.validate((valid) => {
					if (valid) {
						this.fullscreenLoading = true
						if (this.passID !== '') { //有ID，就是保存更新
							UpdateWorkByID({
									ID: this.passID,
									Status: this.Status,
									form: this.form
								})
								.then(res => {
									this.fullscreenLoading = false
									this.$message.success('保存成功')
									this.$emit('goBack')
								})
								.catch(err => {
									this.fullscreenLoading = false
								})
						} else { //无ID就是新建
							AddWork({
									form: this.form
								})
								.then(res => {
									this.fullscreenLoading = false
									this.$message.success('新建成功')
									this.$emit('goBack')
								})
								.catch(err => {
									this.fullscreenLoading = false
								})
						}
					} else {
						return false
					}
				})
			},



			//智能下拉---
			querySearch(queryString, cb) {
				let values = this.combolist.easy; //传入下拉列表数组
				let results = queryString ? values.filter(this.createFilter(queryString)) : values;
				// 调用 callback 返回建议列表的数据
				cb(results);
			},
			querySearch2(queryString, cb) {
				let values = this.combolist.address; //传入下拉列表数组
				let results = queryString ? values.filter(this.createFilter(queryString)) : values;
				// 调用 callback 返回建议列表的数据
				cb(results);
			},
			createFilter(queryString) {
				return (e) => {
					return (e.value.toLowerCase().indexOf(queryString.toLowerCase()) === 0);
				}
			},
			//智能下拉---	





		},
	}
</script>

<style>
	.hide .el-upload--picture-card {
		display: none;
	}
</style>

<vue-filename-injector>
export default function (Component) {
  Component.options.__source = "src/views/pages/WorkInfo/WorkEdit.vue"
}
</vue-filename-injector>
